// PlainView.java — recomputes the aggregate live on EVERY query (always fresh)
package com.nbi.db;

import java.util.*;

public class PlainView {
    private final List<Txn> base; // reference to LIVE base data

    public PlainView(List<Txn> base) { this.base = base; }

    // No stored result: runs the SELECT each time -> always current.
    public Map<String,Double> totalsPerBranch() {
        Map<String,Double> out = new TreeMap<>();
        for (Txn t : base) out.merge(t.branch, t.amount, Double::sum);
        return out;
    }
}
