// MaterializedView.java — stores a snapshot; stale until refresh() is called
package com.nbi.db;

import java.util.*;

public class MaterializedView {
    private final List<Txn> base;
    private Map<String,Double> snapshot = new TreeMap<>(); // STORED result
    private long refreshedAtSeq;                           // "timestamp" of snapshot

    public MaterializedView(List<Txn> base) { this.base = base; refresh(0); }

    // Compute once and persist the snapshot (expensive query runs here only).
    public void refresh(long seq) {
        Map<String,Double> computed = new TreeMap<>();
        for (Txn t : base) computed.merge(t.branch, t.amount, Double::sum);
        this.snapshot = computed;
        this.refreshedAtSeq = seq;
    }

    // Reads hit the stored snapshot -> fast, but possibly stale.
    public Map<String,Double> totalsPerBranch() { return snapshot; }
    public long refreshedAt() { return refreshedAtSeq; }
}
