// Demo.java — contrasts fresh plain view vs stale-until-refresh materialized view
package com.nbi.db;

import java.util.*;

public class Demo {
    public static void main(String[] args) {
        List<Txn> base = new ArrayList<>(List.of(
            new Txn("BR01", 10000), new Txn("BR01", 5000), new Txn("BR02", 8000)
        ));

        PlainView plain = new PlainView(base);
        MaterializedView mat = new MaterializedView(base); // snapshot taken at seq 0

        System.out.println("Before new deposit:");
        System.out.println("  plain view (live)      = " + plain.totalsPerBranch());
        System.out.println("  materialized (snap @0) = " + mat.totalsPerBranch());

        // A new large deposit arrives in the base table AFTER the snapshot.
        base.add(new Txn("BR01", 100000));

        System.out.println("After new 100000 deposit to BR01, BEFORE refresh:");
        System.out.println("  plain view (live)      = " + plain.totalsPerBranch()
                + "   <- reflects new deposit (fresh)");
        System.out.println("  materialized (snap @0) = " + mat.totalsPerBranch()
                + "   <- STALE, old snapshot");

        mat.refresh(15); // scheduled 15-min refresh runs
        System.out.println("After REFRESH:");
        System.out.println("  materialized (snap @" + mat.refreshedAt() + ") = "
                + mat.totalsPerBranch() + "   <- now up to date");
    }
}
